package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaKokDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_rahmataka_arju" to DuaText("तुजी दया मेळपाची म्हाका आशा आसा.", "हे अल्लाह, तुज्या दयेची हांव आस्त दवरता, देखून म्हाका एक दोळो लेगीत म्हजेचेर सोडचो न्हय, आनी म्हजें सगळे काम सारकें कर. तुज्या शिवाय देव ना.", "त्रासांत आशिल्ल्या व्यक्तीचो दुआ (दावत अल-मक्रूब).", "पैगंबर सल्ल्याह अलियाह वसलमान ताका त्रासांत आशिल्ल्या व्यक्तीचो दुआ अशें नांव दिलें."),
        "dua_against_enemy_ahzab" to DuaText("दुस्मानांच्या सैन्या आड", "हे अल्लाह, पुस्तक उघड करपी, गिणपाक बेगीन! संघराज्यांक हारय. हे अल्लाह, तांकां हारय आनी हालय.", "दुस्मानाविरूद्ध-संघराज्याच्या झुजाचो दुआ.", "दुस्मानाविरूद्ध पैगंबरान सल्ल्याह अल्लीह वस्लम दुआ केला."),
        "dua_anta_adudi" to DuaText("तूं म्हजो आदार", "हे अल्लाह, तूं म्हजो आदार आनी म्हजो सहाय्यक. हांव तुज्या वरवीं येवजण करता, तुज्या वरवीं हांव फुडें वता आनी तुज्या वरवीं हांव झुजतां.", "सर्त वा व्हड आव्हान पयलीं.", "पैगंबर सल्ल्याह अलियाह वसलमान हें झुजांत सांगलें."),
        "dua_ikfinihim" to DuaText("तांचे आड म्हाका फावो", "हे अल्लाह, तूं जाय तितलो म्हजे आड फावो.", "जुलमी लोकांच्या वायटपणा आड-पीपल्स ऑफ द डिच्या कथेत चल्याचे दुआ.", "अल्लाहान त्या चल्याक जुलमी लोकां पसून वाटायलो."),
        "dua_qadarullah" to DuaText("जेन्ना कितें तरी वायट घडटा", "हो अल्लाहचो हुकूम, आनी ताणें आपली इत्सा केल्ली.", "जेन्ना कितें तरी अप्रिय घडटा, तेन्ना'जर फकत'म्हणचे बदला.", "'जर फकत'शयतनाचें दार उगडटा."),
        "dua_ala_kulli_hal" to DuaText("दरेक परिस्थितींत तोखणाय कर", "दरेक परिस्थितींत सगळ्यो तोखणाय अल्लाहाक आसा.", "जेन्ना कितें तरी नापसंद जाता.", "पैगंबर सल्ल्यल्लाह अलीह वसलमान ताका आवडनाशिल्ल्या एका गजालीक तोंड दिवन हें सांगलें."),
        "dua_dogs_barking" to DuaText("रातचें आयकुपाक कुत्रे भुंकतात", "शापित शयताना कडल्यान हांव अल्लाहाक आलाशिरो मागता.", "आयकून रातचें कुत्रे भुलोवन वा गाढव हांची गांड काडटात.", "जे तूं पळोवंक ना तें ते पळयतात."),
        "dua_leaving_home_adilla" to DuaText("चुकून वचपा पसून शरण", "हे अल्लाह, हांव चुकूं वा चुकूं, हांव चुकूं वा चुकूं, हांव चुकूं वा अन्याय जावूं, म्हाका मूर्खपणाचें वागणूक मेळूं वा मूर्खपणाचें वागणूक मेळूं अशी परिस्थिती येवची न्हय, हांव तुजो आलाशिरो मागता.", "घरांतल्यान भायर सरतना-उम्म सलामाह (आर. ए.) हाणें कथन केलां.", "पैगंबर सल्लल्लाह अल्लीह वसलमान जेन्ना जेन्ना घराच्यान भायर सरलो तेन्ना हो पठण करतालो."),
        "dua_ascending_descending" to DuaText("वयर वचप आनी सकयल येवप", "(वयर वतना) अल्लाह सगळ्यांत व्हड आसा.-(सकयल पडल्यार) अल्लाहाक महिमा.", "प्रवासांत वयर वतना'अल्लाहू अकबर \"आनी सकयल वतना'सुभानल्लाह\" अशें म्हणात.", "प्रवास करतना साथीदारांची (आर. ए.) पद्दत."),
        "dua_traveller_sahar" to DuaText("सकाळ जावचे पयलीं भोंवडेकारांचो दुआ", "एका आयकुप्यान आमची अल्लाहाची तोखणाय आनी आमचेर ताणें केल्ल्या बरपांचीं उपकारां आयकून (आनी फुडें व्हरून) दिल्या. हे म्हारजे, आमचे वांगडा चल आनी आमचेर तुजी कृपा कर-(हांव अशें म्हणतां) अग्नी पसून अल्लाहांत आलाशिरो घेवप.", "भोंवड्यार, सकाळ जावचे पयलीं.", "पयशांनी पयशांच्या पयशांनी पयशांच्या पयशांनी हें सांगलें."),
        "dua_zawwadakallah" to DuaText("भोंवडेकाराकः अल्लाह ताका तक्वा दिवचो.", "अल्लाह तुज्या प्रवासा खातीर तुका तकवा दिवचो, तुज्या पापांक माफ कर आनी तूं जंय आसशील थंय तुजे खातीर बरें कर.", "जेन्ना भोंवडेकाराक निरोप दितात.", "पयशांनी पैगंबर सल्लल्लाह अलियाह वसलमान प्रवासाक भायर सरपी कोणाक तरी ही दुआ दिली."),
        "dua_traveller_to_resident" to DuaText("फाटल्यान रावपी लोकांक भोंवडेकार", "हांव तुका अल्लाहाक सोपयता, जाचेरचो विस्वास केन्नाच ना.", "कुटुंबाक निरोप दितना भोंवडेकारान सांगलें.", "कुटुंबाची सुरक्षाव्यवस्था अल्लाहाक सोपोवप."),
        "dua_entering_village" to DuaText("शार वा गांवांत प्रवेश करप", "हे सात स्वर्गांचो आनी ते सगळ्यांची सावळीचो स्वामी, सात धर्तरेचो आनी तीं व्हरपी सगळ्यांचो स्वामी, भुतांचो आनी ते सगळ्यांचो दिशाभूल करपी, वाऱ्याचो आनी ते सगळ्यांचो, वाऱ्यांचो आनी ते सगळ्यांचो, प्रभू! आमी तुज्या कडेन ह्या शाराचो आनी ताच्या लोकांचो बरो सोदतात, आनी आमी तुज्या कडेन ताच्या वायट, ताच्या लोकांच्या वायट आनी तातूंतल्या वायट गजालीं पसून आलाशिरो सोदतात.", "खंयच्याय शारांत वा शारांत प्रवेश करचे पयलीं.", "पैगंबर सल्लल्लाह अल्लीह वसलमान जेन्ना जेन्ना शारांत प्रवेश करपाची इत्सा आसत तेन्ना हो पठण करताले."),
        "dua_vehicle_stumbles" to DuaText("जेन्ना वाहन आडखळटा", "अल्लाहच्या नांवान.", "जेन्ना'शयतान नाश जावंक शकता \"अशें म्हणचे बदला, दोंगर वा वाहन घसरता वा आडखळी येता.", "बिस्मिल्लाह म्हणिल्ल्यान शायतान माशेच्या आकारा मेरेन सुको जाता."),
        "dua_ajz_kasal_haram" to DuaText("दुबळेपण आनी जाण्टेपण हांचे पसून शरण", "हे अल्लाह, हांव असहायताय आनी आळशीपण, भ्याडपण आनी जाण्टेपण, जिवीत आनी मरणाच्या कसोटीं पसून, आनी कबरीची ख्यास्त हांचे पसून तुका आलाशिरो मागता.", "एक पुराय दिसपट्टो आलाशिरो.", "पैगंबर सल्ल्याह अलियाह मुसलमानान चड करून एक दुआ केली."),
        "dua_sharri_ma_amiltu" to DuaText("म्हज्या वायट कामांतल्यान शरण घे.", "हे अल्लाह, हांवें जे केलां ताचे वायट आनी जे करूंक ना ताचे वायट हांचे पसून हांव तुका आलाशिरो मागता.", "आयशा (रा.) हाच्या मतान पैगंबर सल्ल्याह अलियाह वसलमाचो एक दुआ.", "कितें केलें आनी कितें रद्द केलें ह्या दोनूय परिणामां पसून संरक्षण."),
        "dua_jahdil_bala" to DuaText("गंभीर चांचण्यांतल्यान आश्रय", "हे अल्लाह, खर खटल्यां पसून, दुख्खाक लागून, वायट आदेशाक लागून आनी दुस्मानांच्या गर्वाक लागून हांव तुका आलाशिरो मागता.", "खर कसोटीं आनी दुस्मानांच्या हर्षाभितरावपा पसून शरण घे.", "पैगंबर सल्लल्लाह अलियाह वसलमान ह्या चार गजालीं पसून आलाशिरो घेतलो."),
        "dua_fitnat_ghina_faqr" to DuaText("संपत्ती आनी गरिबीच्या चांचण्यांतल्यान शरण", "हे अल्लाह, आळस आनी जाण्टेपण, पाप आनी रिण, कबरीची खटलो आनी ख्यास्त, अग्नीची खटलो आनी ख्यास्त, संपत्तीच्या खटल्याच्या वायट गजालीं पसून, आनी गरिबीच्या खटल्या पसून हांव तुका आलाशिरो मागता.", "कबर, नरक, संपत्ती आनी गरिबी (दुआचो एक भाग) ह्या कसोटींतल्यान शरण घे.", "पैगंबर सल्ल्याह अल्लीह वसलमा कडल्यान आलाशिरो घेवपाची एक व्यापक दुआ."),
        "dua_kufr_faqr" to DuaText("अविश्वास आनी गरिबी पसून आश्रय", "हे अल्लाह, हांव तुका अविश्वास आनी गरिबी पसून आलाशिरो मागता, आनी हुंबराच्या ख्यास्तेकडल्यान हांव तुका आलाशिरो मागता. तुज्या शिवाय देव ना.", "तीन फावटीं सकाळीं आनी सांजीं.", "अबू बक्रान (र.) पैगंबर सल्लल्लाह् अलैहि वसल्लमाचें हें सांगप आयकून घेतलें."),
        "dua_sharri_sami" to DuaText("म्हज्या इंद्रियांच्या वायटपणांतल्यान शरण घे", "हे अल्लाह, म्हज्या आयकुपाक लागून जावपी वायट, म्हज्या नदरेंतलें वायट, म्हज्या जीबेंतलें वायट, म्हज्या काळजाचें वायट आनी म्हज्या इत्सेच्या वायट हांचे पसून हांव तुका आलाशिरो मागता.", "शकल इब्न हुमायद (रा.) हाका शिकयलो.", "पांय आनी स्वताक पापा पसून वाटावपा खातीर एक दुआ."),
        "dua_hadm_gharaq" to DuaText("अचकीत मरण आनी अपघातां पसून आश्रय", "हे अल्लाह, हुं तुज्या कडेन (इमारतीचे) पिडपा पसून, उंचाये वयल्यान पडपा पसून, बुडप, जळप आनी जाण्टेपण हांचे पसून, मरणाच्या वेळार म्हाका दिशाभूल करपी शयतानांतल्यान, तुज्या वाटेरल्यान पळून वचतना मरण येवपा पसून, आनी (विखारी) दंशाक लागून मरण येवपा पसून आलाशिरो मागता.", "अपघात आनी वायट मरणा पसून शरण घेवचें.", "पैगंबर सल्ल्याह अलियाह वसलमा कडल्यान आलाशिरो घेवपाचो दुआ."),
        "dua_ju_khiyanah" to DuaText("उपासमार आनी विश्वासघात हांचे पसून शरण", "हे अल्लाह, हांव तुजो उपासमार जावपाचो आलाशिरो मागता, कारण तो एक वायट साथीदार आसा, आनी हांव तुका विश्वासघात जावचो न्हय असो आलाशिरो मागता, कारण तो एक वायट विश्वासू आसा.", "भूक आनी विश्वासघात हांचे पसून शरण घे.", "पैगंबर सल्ल्याह अलियाह वसलमा कडल्यान आलाशिरो घेवपाचो दुआ."),
        "dua_huda_tuqa" to DuaText("मार्गदर्शन, धर्मनिष्ठा, पवित्रताय आनी पुरेशीपण", "हे अल्लाह, हांव तुका मार्गदर्शन, धर्मनिष्ठा, पवित्रताय आनी स्वयंपूर्णताय मागता.", "पैगंबर सल्ल्याह अल्लीह वसलमाचो एक ल्हानसो, व्यापक दुआ.", "धर्माचे आनी ह्या जगाचे चार मुळावे आशीर्वाद."),
        "dua_aslih_li_dini" to DuaText("म्हजो धर्म, जग आनी उपरांत सुदार.", "हे अल्लाह, म्हजो धर्म बरो कर, जो म्हज्या सगळ्या गजालींची राखण करपी आसा; म्हजें सांसारिक जिणे सारकें कर, तातूंत म्हजी उदरनिर्वाह आसा; आनी म्हजें आख़िरत सारकें कर, जाचेर हांव परत येतलो. म्हजे खातीर दरेक बरेपणांत जिवीत वाडय, आनी म्हजे खातीर दरेक वायटपणांतल्यान मरणाक एक सुटको कर.", "धर्म, हें जग आनी उपरांत-हे तिगोय सुदारणे.", "पैगंबर सल्ल्याह अलियाह वसलमाचो एक व्यापक दुआ."),
        "dua_musarrifal_qulub" to DuaText("तुज्या आज्ञा पाळपा कडेन आमचें काळज वळोव.", "हे अल्लाह, काळजाचो बदल करपी, तुज्या आज्ञा पाळपा कडेन आमचीं काळजां वळोव.", "आज्ञा पाळपाक काळज घटमूट दवरपा खातीर एक दुआ.", "सगळ्या लोकांची काळीज परम करुणामायाच्या दोन बोटांच्या मदीं आसता."),
        "dua_jannah_nar" to DuaText("जन्ना, उज्यांतल्यान शरण मागप", "हे अल्लाह, हांव तुजे कडेन स्वर्ग मागता आनी उजे पसून तुजे कडेन आलाशिरो मागता.", "ताशाहहुदा उपरांत वा खंयच्याय वेळार.", "पैगंबर सल्ल्याह अलियाह वसलमान सांगलेंः आमचे दुआय हाचे भोंवतणी भोंवतात."),
        "dua_khayri_kullih" to DuaText("आतां आनी उपरांत सगळें बरें.", "हे अल्लाह, हांव तुका सगळें बरें मागता-तात्काळ आनी कळपी, म्हाका कितें कळटा आनी कितें कळना-आनी हांव तुका सगळ्या वायट गजालीं पसून आलाशिरो मागता-रोखडेंच आनी कळपी, जें म्हाका कळटा आनी जें म्हाका खबर ना. हे अल्लाह, हांव तुका स्वर्ग मागता आनी खंयचींय उतरां आनी कामां म्हाका ताचे लागीं हाडटात, आनी हांव अग्नी पसून आनी खंयच्याय उतरां आनी कृतींतल्यान म्हाका ताचे लागीं हाडटात ताचे पसून तुजो आलाशिरो मागता.", "पैगंबर सल्ल्याह अलियाह वसलमान आयशा (आर. ए.) (दुआचो एक भाग) हाका ही व्यापक दुआ शिकयली.", "एक दुआ जी सगळीं बरी वस्त एकठांय करता."),
        "dua_ihdini_saddidni" to DuaText("म्हाका मार्गदर्शन कर आनी म्हाका स्पश्ट दवर", "हे अल्लाह, म्हाका मार्गदर्शन कर आनी म्हाका योग्य मार्गार दवर.", "पैगंबर सल्ल्याह अलियाह वसलमान अली (रा.) हाका तें शिकयलें.", "मार्गाचेर मार्गदर्शन करप अशें, आनी सादादाचें बाण सरळ करप असो विचार करात."),
        "dua_hubbaka" to DuaText("अल्लाहाक मोग मागप", "हे अल्लाह, हांव तुजो मोग मागता, तुजेचेर मोग करपी लोकांचो मोग, आनी म्हाका तुज्या मोगाक हाडपी कामां. हे अल्लाह, तुजो मोग म्हाका म्हज्या परस, म्हज्या कुटुंबा परस आनी थंड उदका परस चड प्रिय कर.", "पैगंबर सल्ल्याह अलियाह वसलमान संबंदीत केल्ल्या दावूदाच्या दुआचो (ए. एस.).", "अल्लाहाकडेन मोग करप ही सगळ्यांत व्हड संपत्ती."),
        "dua_filal_khayrat" to DuaText("बरें करप आनी वायट सोडप", "हे अल्लाह, म्हाका बरे काम करपाक, वायट काम सोडून आनी गरीबांचेर मोग करपाक, आनी तूं म्हाका माफ कर आनी म्हजेचेर दया कर. आनी जेन्ना तूं लोकांचेर खटलो घेवपाचो विचार करता तेन्ना म्हाका कसलोच कसलो कसलो नासतना घे. हांव तुजो मोग, तुजेचेर मोग करपी लोकांचो मोग, आनी म्हाका तुज्या मोगाच्या लागीं हाडपी कामांचो मोग मागता.", "अल्लाहान पैगंबर सल्ल्याह अलियाह वसलमाक ही दुआ स्वप्नांत शिकयली.", "पैगंबर सल्ल्याह अलियाह वसलमान सांगलेंः हें खरें, देखून तें शिकात आनी शिकयात."),
        "dua_bi_ilmikal_ghayb" to DuaText("जीण बरी आसल्यार म्हाका जगपाक दिवचें.", "हे अल्लाह, तूं नदरेल्या गजालीं विशीं जाणा आनी सृष्टीचेर तुज्या सामर्थ्यान-जो मेरेन म्हाका जिवीत दवर, जो मेरेन तुका जिवीत बरें हें खबर आसा, आनी जेन्ना म्हाका मरण बरें हें तुका खबर आसत जाल्यार म्हाका घे. हे अल्लाह, हांव तुका गुपीत आनी भौशीक भियेवपाक मागता, समाधानांत आनी रागांत सत्याचे वचन, आनी गरिबी आनी संपत्तींत संयम दवरपाक.", "अम्मार इब्न यासीर (आर. ए.) (उक्तावपी भाग) हाची प्रार्थना दुआ.", "पैगंबर सल्ल्याह अलियाह वसलमान प्रार्थनेंत ही दुआ केली."),
        "dua_ism_azam_mannan" to DuaText("इस्मे-ए-आझमः अल-मन्नान", "हे अल्लाह, हांव तुका मागता, कारण सगळी तोखणाय तुजेच आसली. तुज्या शिवाय कोणूच देव ना, तो उपकार दिवपी, स्वर्ग आनी धर्तरेचो निर्मातो. हे वैभव आनी सन्मान मेळोवपी, हे सदासर्वकाळ जगपी, हे पालन करपी!", "पैगंबर सल्लल्लाह अलीह वसलमान सांगलें की ह्या मनशान अल्लाहच्या व्हडल्या नांवान दुआ केली.", "ह्या नांवान तयार केल्ल्या दुआक जाप मेळटा."),
        "dua_ism_azam_ahad_samad" to DuaText("इस्मे-ए-आझमः अल-अहद अस-समद", "हे अल्लाह, हांव तुका मागता, कारण तूंच अल्लाह आसा हाची हांव साक्षी दिता; तूं, एक, स्वयंपूर्ण, जल्माक येवंक वा जल्माक येवंक ना, आनी ताचे कडेन तुलना करपाक कोणूच ना, ताचे भायर कोणूच देव ना.", "पैगंबर सल्लल्लाह अलीह वसलमान सांगलें की ह्या मनशान अल्लाहाक ताच्या व्हडल्या नांवान विचारलें.", "ताचे वरवीं विचारल्यार तो दिता; जेन्ना ताका हाक मारता तेन्ना तो जाप दिता."),
        "dua_thabbitni_hadiyan" to DuaText("म्हाका खंबीर, मार्गदर्शक आनी मार्गदर्शक कर", "हे अल्लाह, म्हाका घटमूट कर, आनी म्हाका मार्गदर्शन करपी आनी मार्गदर्शन दिवपी कर.", "पैगंबर सल्ल्याह अलियाह वस्लमान जरीर (रा) खातीर ही दुआ केली (स्वता खातीर'थाबितनी'अशें म्हणात).", "जरीर (आर. ए.) खातीर मूळ दुआत'थब्बिट-हु \"हे उतर वापरतात."),
        "dua_rabbighfir_tub_alayya" to DuaText("म्हाका माफ कर आनी म्हजो पश्चात्ताप मान्य कर.", "म्हज्या प्रभू, म्हाका माफ कर आनी म्हजो पश्चात्ताप मान्य कर. खरें म्हणल्यार तूं पश्चात्तापाचो कर्तो, दयाळू.", "एकाच बसकेंत शंबर फावटीं-पैगंबर सल्ल्याह अलियाह वसलमाचो सराव.", "साथीदारांनी पयगंबर सल्ल्याह अलियाह वसलमान एकाच बसकेंत शंबर फावटीं म्हटिल्ली गणीत केली."),
        "dua_rafiq_ala" to DuaText("मरण पावपी मनशाचो दुआ", "हे अल्लाह, म्हाका माफ कर, म्हजेचेर दया कर आनी म्हज्या सर्वोच्च साथीदाराकडेन सामील जाव.", "पैगंबर सल्ल्याह अलियाह वसलमाचो निमाणो दुआ-दुयेंत मनशाक स्वता खातीर सांगपाक.", "पैगंबर सल्ल्याह अलियाह वसलमान ताच्या निधना वेळार ही दुआ केली."),
        "dua_la_bas_tahur" to DuaText("दुयेंतीक सांत्वन दिवप-शुध्दीकरण", "कांयच लुकसाण ना; अल्लाह जाय जाल्यार तें शुध्दीकरण (पापांतल्यान).", "भेट दितना दुयेंतींचें सांत्वन करचें.", "पैगंबर सल्ल्याह अलियाह वसलमान दुयेंतींक भेट दितना हें सांगलें."),
        "dua_talqeen" to DuaText("मरण येवपी लोकां खातीर तालकीन", "अल्लाह सोडून कोणाकूच पुजा करपाचो अधिकार ना.", "मरण पावपी मनशा लागीं कलिमा पठण कर (तांकां सांगपाक सक्ती करची न्हय).", "जाचे निमाणें उतर'ला इलाहा इल्लल्लाह \"आसतलें ते स्वर्गांत प्रवेश करतले (अबू दाउद 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("मरणाची इत्सा करपा बदला", "हे अल्लाह, जो मेरेन म्हाका जिवीत बरें आसा तें मेरेन म्हाका जिवीत दवर, आनी जेन्ना मरण म्हाका बरें जाता तेन्ना म्हाका घेवन चल.", "त्रासांत मरण येवपाची इत्सा करपा बदला.", "पैगंबर सल्ल्याह अलियाह वसलमान मरणाची इत्सा करपाक मनाई केली आनी ताचे बदला हें शिकयलें."),
        "dua_for_one_i_cursed" to DuaText("कोणाकूय हांव उतरांनी दुखयता", "हे अल्लाह, ज्या खंयच्याय श्रद्धेक हांवें अपमान केला, ताका पुनरुत्थान दिसा ताचे खातीर तुका लागीं येवपाचें साधन कर.", "कोणाकूय रागान वायट उलयताले.", "पैगंबर सल्ल्याह अलियाह वसलमाचो एक दुआ."),
    )
}
